-- DWA-M-820-3 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-06).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261006220000_m820_3_hints.sql
-- Rollback: scripts/migrations/rollback-20261006220000_m820_3_hints.sql
BEGIN;
UPDATE fields x SET description = 'Mehrfachauswahl aller beauftragten Leistungsphasen (LPH 0–9). Das Vorwort (gedruckt S. 3) nennt die Leistungsphasen „von der Bedarfsplanung (LPH 0) bis zur Objektbetreuung (LPH 9)“; § 2.1 (S. 8) nennt die neun Leistungsphasen der HOAI bzw. die Projektstufen des AHO. Dokumentiert den Leistungsumfang; die Sichtbarkeit der Blätter steuert der Projekttyp. Pflichtangabe.
[EN] Multi-select every contracted service phase (LPH 0–9). The Vorwort (printed p. 3) names the phases "from needs planning (LPH 0) to property support (LPH 9)"; § 2.1 (p. 8) names the nine HOAI service phases or the AHO project stages. Documents the scope of services; sheet visibility is driven by the project type. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'applicable_lph';
UPDATE fields x SET description = 'Name des Auftraggebers. § 1 (gedruckt S. 7): „Das Merkblatt richtet sich an Auftraggeber und Auftragnehmer (beauftragte Ingenieurbüros) …“. Die Blockade REQ-01 liest dieses Feld und ist erst bestanden, wenn es ausgefüllt ist. Pflichtangabe.
[EN] Name of the client (Auftraggeber). § 1 (printed p. 7): "The Merkblatt addresses clients and contractors (appointed engineering offices) …". Block gate REQ-01 reads this field and passes only once it is filled in. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Interne Vertrags- oder Auftragsnummer zur Projektzuordnung. Das Merkblatt macht hierzu keine inhaltliche Vorgabe; reine Registrierungsangabe für die Projektakte.
[EN] Internal contract or order number for cross-referencing the project. The Merkblatt makes no content requirement here; a purely administrative registration field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'contract_reference';
UPDATE fields x SET description = 'Name des Auftragnehmers (beauftragtes Ingenieurbüro). § 1 (gedruckt S. 7): „Das Merkblatt richtet sich an Auftraggeber und Auftragnehmer (beauftragte Ingenieurbüros)...“ Wird von REQ-01 geprüft. Pflichtangabe.
[EN] Name of the contractor (the appointed engineering office). § 1 (printed p. 7): "The Merkblatt addresses clients and contractors (appointed engineering offices)..." Checked by REQ-01. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'contractor_auftragnehmer';
UPDATE fields x SET description = 'Ja/Nein: gilt für dieses Projekt auch Teil 1 der Reihe DWA-M 820 (Vorbereitung und Vergabeverfahren, März 2020)? Reine Projektabgrenzung, keine inhaltliche Prüfung in Teil 3.
[EN] Yes/No: does Part 1 of the DWA-M 820 series (Vorbereitung und Vergabeverfahren, March 2020) also apply to this project? A scoping flag only; Part 3 enforces nothing from it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'part1_applicable';
UPDATE fields x SET description = 'Ja/Nein: gilt für dieses Projekt auch Teil 2 (Durchführung, April 2023)? Reine Projektabgrenzung, keine inhaltliche Prüfung in Teil 3.
[EN] Yes/No: does Part 2 (Durchführung, April 2023) also apply to this project? A scoping flag only; Part 3 enforces nothing from it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'part2_applicable';
UPDATE fields x SET description = 'Geografischer Standort des Vorhabens. Reine Registrierungsangabe, vom Merkblatt nicht inhaltlich vorgegeben.
[EN] Geographic location of the project. A purely administrative registration field; the Merkblatt makes no content requirement here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Projekttitel zur Wiedererkennung in diesem und verknüpften Arbeitsblättern. Reine Registrierungsangabe.
[EN] Project title used to identify the project across this and linked worksheets. A purely administrative registration field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Interne Projektnummer/ID. Reine Registrierungsangabe, vom Merkblatt nicht inhaltlich vorgegeben.
[EN] Internal project number/ID. A purely administrative registration field; the Merkblatt makes no content requirement here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Legt fest, ob dieses Projekt die Gesamtsystem-Phasen (§ 5.2–5.4), die Einzelprojekt-Phasen (§ 6.2–6.7) oder beide durchläuft. § 4 (gedruckt S. 11): „Die Aufteilung in ''Konzept für das Gesamtsystem'' und ''Projekte'' ist dabei eine elementare Grundlage.“ Steuert die Sichtbarkeit zahlreicher Folgeblätter. Pflichtangabe.
[EN] Determines whether this project runs the overall-system phases (§ 5.2–5.4), the single-project phases (§ 6.2–6.7), or both. § 4 (printed p. 11): "The division into ''concept for the overall system'' and ''projects'' is an elementary basis." Drives visibility of many downstream sheets. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'project_type';
UPDATE fields x SET description = 'Datum, an dem das Projekt in diesem Workbook angelegt wurde. Reine Registrierungsangabe.
[EN] Date the project was registered in this workbook. A purely administrative registration field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'registration_date';
UPDATE fields x SET description = 'Ja/Nein: betrifft das Projekt den Bereich Abfall? § 1 (gedruckt S. 7): „...bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.“ Die Blockade REQ-01 ist bestanden, wenn mindestens einer der vier Bereiche bejaht ist.
[EN] Yes/No: does the project involve the waste (Abfall) field? § 1 (printed p. 7): "...in the construction of facilities in the fields of water management, hydraulic engineering, wastewater and waste." Block gate REQ-01 passes when at least one of the four fields is Yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_abfall';
UPDATE fields x SET description = 'Ja/Nein: betrifft das Projekt den Bereich Abwasser? § 1 (gedruckt S. 7): „...bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.“ Die Blockade REQ-01 ist bestanden, wenn mindestens einer der vier Bereiche bejaht ist.
[EN] Yes/No: does the project involve the wastewater (Abwasser) field? § 1 (printed p. 7): "...in the construction of facilities in the fields of water management, hydraulic engineering, wastewater and waste." Block gate REQ-01 passes when at least one of the four fields is Yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_abwasser';
UPDATE fields x SET description = 'Ja/Nein: betrifft das Projekt den Bereich Wasserbau? § 1 (gedruckt S. 7): „...bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.“ Die Blockade REQ-01 ist bestanden, wenn mindestens einer der vier Bereiche bejaht ist.
[EN] Yes/No: does the project involve the hydraulic-engineering (Wasserbau) field? § 1 (printed p. 7): "...in the construction of facilities in the fields of water management, hydraulic engineering, wastewater and waste." Block gate REQ-01 passes when at least one of the four fields is Yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_wasserbau';
UPDATE fields x SET description = 'Ja/Nein: betrifft das Projekt den Bereich Wasserwirtschaft? § 1 (gedruckt S. 7): „...bei der Herstellung von Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.“ Die Blockade REQ-01 ist bestanden, wenn mindestens einer der vier Bereiche bejaht ist.
[EN] Yes/No: does the project involve the water-management (Wasserwirtschaft) field? § 1 (printed p. 7): "...in the construction of facilities in the fields of water management, hydraulic engineering, wastewater and waste." Block gate REQ-01 passes when at least one of the four fields is Yes.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sector_wasserwirtschaft';
UPDATE fields x SET description = 'Mehrfachauswahl derselben vier gedruckten Bereiche (§ 1) neben den Einzel-Booleans sector_*; REQ-01 prüft weiterhin die Booleans. Funktionales Zweitfeld, keine eigene Prüfung.
[EN] A multi-select mirroring the same four printed fields (§ 1) alongside the individual sector_* booleans; REQ-01 still reads the booleans. A functional duplicate field, not independently checked.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.symbol = 'sektoren';
UPDATE compliance_requirements x SET description = 'Blockierende Prüfung, gilt immer: bestanden, wenn mindestens einer der vier Bereiche (Wasserwirtschaft, Wasserbau, Abwasser, Abfall) bejaht ist und Auftraggeber und Auftragnehmer eingetragen sind (alle auf diesem Blatt). Grund: § 1 (gedruckt S. 7) – das Merkblatt gilt für „Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall“ und „richtet sich an Auftraggeber und Auftragnehmer“.
[EN] Block gate, always applies: passes when at least one of the four fields (water management, hydraulic engineering, wastewater, waste) is Yes and both client and contractor are entered (all on this sheet). Reason: § 1 (printed p. 7) – the Merkblatt covers "facilities in the fields of water management, hydraulic engineering, wastewater and waste" and "addresses clients and contractors".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND x.code = 'REQ-01';
UPDATE fields x SET description = 'Bestätigung Anwendungshinweis 1 (§ 1, gedruckt S. 7): „Im konkreten Projekt werden aus den Qualitätselementen die projektspezifischen Anforderungen und Aufgabenlisten, inklusive Zuständigkeiten, vom Anwendenden entwickelt und in Arbeitsunterlagen (beispielsweise Checklisten) dokumentiert.“ Warnung bei REQ-02, keine Blockade.
[EN] Confirmation of Application note 1 (§ 1, printed p. 7): "In the specific project the user develops the project-specific requirements and task lists, including responsibilities, from the quality elements and documents them in working papers (e.g. checklists)." Feeds warning gate REQ-02, not a block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_1_confirmed';
UPDATE fields x SET description = 'Bestätigung Anwendungshinweis 2 (§ 1, gedruckt S. 7): „Es wird darauf hingewiesen, dass die bereitgestellten Qualitätselemente einzelne Anhaltspunkte für die Projektabwicklung darstellen. Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“ Warnung bei REQ-02.
[EN] Confirmation of Application note 2 (§ 1, printed p. 7): "The provided quality elements are only individual pointers for project execution; completion for the specific project tasks is carried out in the project team." Feeds warning gate REQ-02.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_2_confirmed';
UPDATE fields x SET description = 'Bestätigung Anwendungshinweis 3 (§ 1, gedruckt S. 7): „Die Qualitätselemente unterstützen die Bearbeitenden dabei, die Leistungen, die zum Projekterfolg beitragen, auch im Austausch innerhalb des Projektteams, zu identifizieren und systematisch abzuarbeiten.“ Warnung bei REQ-02.
[EN] Confirmation of Application note 3 (§ 1, printed p. 7): "The quality elements help those working on the project identify and systematically work through the services that contribute to project success, including through exchange within the project team." Feeds warning gate REQ-02.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_3_confirmed';
UPDATE fields x SET description = 'Bestätigung Anwendungshinweis 4 (§ 1, gedruckt S. 7): „Die vollständige Ablaufstruktur für Projekte aller Art ergibt sich aus der eigenverantwortlichen Anwendung und projektspezifischen Anpassung der im Merkblatt vorgelegten Hinweise.“ Warnung bei REQ-02.
[EN] Confirmation of Application note 4 (§ 1, printed p. 7): "The complete process structure for projects of any kind results from the self-responsible application and project-specific adaptation of the notes presented in the Merkblatt." Feeds warning gate REQ-02.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anw_hinweis_4_confirmed';
UPDATE fields x SET description = 'Bestätigung des Grundsatzes (§ 3, gedruckt S. 10): striktes Kopieren und erneutes Verwenden bereits durchgeführter Verfahrensweisen wird der Anforderung an einen wirtschaftlichen Betrieb eines Gesamtsystems künftig nicht mehr gerecht; ein Umdenken ist erforderlich. Freiwillige Bestätigung, keine Blockade.
[EN] Acknowledgement of the principle (§ 3, printed p. 10): strict copying and re-use of previously executed procedures will no longer meet the requirement of economic operation of an overall system; a rethink is required. Optional acknowledgement, not enforced.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_avoid_strict_copying';
UPDATE fields x SET description = 'Bestätigung des Grundsatzes (§ 3, gedruckt S. 10): Ingenieurbüros sollten die „Treiber“ neuer, zukunftsorientierter Ansätze sein; im Gegenzug muss der Auftraggeber die Projekte so aufsetzen, dass dies möglich ist. Freiwillige Bestätigung.
[EN] Acknowledgement of the principle (§ 3, printed p. 10): planning engineering offices should be the "drivers" of new, forward-looking approaches; in return the client must set up projects so that this is possible. Optional acknowledgement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_engineers_as_drivers';
UPDATE fields x SET description = 'Bestätigung des Grundsatzes (§ 3, gedruckt S. 10): „Es werden bei allen Projektbeteiligten in noch stärkerem Umfang Offenheit und Flexibilität für innovative Ansätze erforderlich sein …“ Freiwillige Bestätigung.
[EN] Acknowledgement of the principle (§ 3, printed p. 10): "All project participants will need even greater openness and flexibility for innovative approaches …" Optional acknowledgement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_innovation_openness';
UPDATE fields x SET description = 'Bestätigung des Grundsatzes (§ 3, gedruckt S. 10): die wirtschaftliche Betriebsphase (Lebenszyklusbetrachtung) ist ein wesentliches Ziel der Planungs- und Bauaktivitäten und wird bereits bei der Konzeption des Gesamtsystems berücksichtigt. Freiwillige Bestätigung.
[EN] Acknowledgement of the principle (§ 3, printed p. 10): the economically efficient operating phase (lifecycle view) is an essential goal of planning and construction, already considered when conceiving the overall system. Optional acknowledgement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_lifecycle_focus';
UPDATE fields x SET description = 'Ja/Nein: wurde die geforderte Zweistufigkeit (erst Gesamtsystembetrachtung, dann Einzelprojekte) tatsächlich angewendet? Nur sichtbar, wenn der Auftraggeber ein kleinerer kommunaler Betrieb ist (Feld auf diesem Blatt); REQ-05 prüft dies als Warnung.
[EN] Yes/No: was the required two-stage approach (overall-system review first, then single projects) actually applied? Only shown when the client is a smaller municipal operator (field on this sheet); checked as a warning by REQ-05.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'grundsatz_two_step_followed';
UPDATE fields x SET description = 'Mehrfachauswahl derselben vier gedruckten Anwendungshinweise (§ 1) neben den Einzel-Booleans anw_hinweis_1…4_confirmed; REQ-02 prüft weiterhin die Booleans. Funktionales Zweitfeld.
[EN] A multi-select mirroring the same four printed application notes (§ 1) alongside the individual anw_hinweis_1…4_confirmed booleans; REQ-02 still reads the booleans. A functional duplicate field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'anwendungshinweise';
UPDATE fields x SET description = 'Ja/Nein: ist der Auftraggeber ein kleinerer kommunaler Betrieb? § 3 (gedruckt S. 10): „Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich...“ Ja blendet die Frage „Zweistufiger Ansatz angewandt“ ein (REQ-05); Nein blendet sie aus. Pflichtangabe.
[EN] Yes/No: is the client a smaller municipal operator? § 3 (printed p. 10): "Smaller municipal operators may draw on external expertise. Here the two-stage approach is required..." Yes reveals the question "Two-stage approach applied" (checked by REQ-05); No hides it. Required.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.symbol = 'kleiner_kommunaler_betrieb';
UPDATE compliance_requirements x SET description = 'Warnprüfung, gilt immer: bestanden, wenn alle vier Anwendungshinweise (§ 1, gedruckt S. 7) auf diesem Blatt bestätigt sind. Das Merkblatt druckt Hinweise, keine Pflicht zur Kenntnisnahme – deshalb Warnung statt Blockade.
[EN] Warning gate, always applies: passes when all four application notes (§ 1, printed p. 7) are confirmed on this sheet. The Merkblatt prints notes, not a duty to acknowledge them – hence a warning, not a block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.code = 'REQ-02';
UPDATE compliance_requirements x SET description = 'Warnprüfung: ist der Auftraggeber ein kleinerer kommunaler Betrieb, muss der zweistufige Ansatz angewendet worden sein. § 3 (gedruckt S. 10): „...Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung...zu erstellen und erst dann Einzelprojekte zu definieren...“ Das gedruckte „erforderlich“ spräche für eine Blockade; die Prüfung ist derzeit als Warnung eingestuft.
[EN] Warning gate: if the client is a smaller municipal operator, the two-stage approach must have been applied. § 3 (printed p. 10): "...the two-stage approach is required, i.e. first an overall-system review...and only then the definition of single projects..." The printed "required" would support a block; the check is currently rated a warning.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND x.code = 'REQ-05';
UPDATE fields x SET description = 'Bestätigung, dass der Ablauf aus Bild 1 (§ 4, gedruckt S. 11: Konzept für das Gesamtsystem → Projekte identifizieren → Projekte einzeln abwickeln) für dieses Projekt übernommen wird. § 4: ein strukturierter Planungsprozess „gibt eine verlässliche und gut funktionierende Struktur“. Prüfung REQ-04 (Warnung).
[EN] Confirmation that the process of Bild 1 (§ 4, printed p. 11: concept for the overall system → identify projects → run each project) is adopted for this project. § 4: a structured planning process "gives a reliable and well-functioning structure". Checked by warning gate REQ-04.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_acknowledged';
UPDATE fields x SET description = 'Markiert Schritt 1 aus Bild 1 (§ 4, gedruckt S. 11): „Bedarfsplanung ''Konzept'' durchführen“ — die früheste Phase einer übergeordneten Maßnahmenplanung, vor jedem Einzelprojekt. Rein dokumentarisch, keine eigene Prüfung.
[EN] Marks step 1 of Bild 1 (§ 4, printed p. 11): "Carry out Bedarfsplanung ''Konzept''" — the earliest phase of an overarching measure plan, before any single project. Documentary only, no gate of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_1_bedarfsplanung_konzept';
UPDATE fields x SET description = 'Markiert Schritt 2 aus Bild 1 (§ 4/§ 5.3, gedruckt S. 11–12/13): „Konzept (Gesamtsystem) entwickeln“ — das eigentliche Konzept entsteht; Einzelmaßnahmen und ihre Investitionen lassen sich dadurch oft vermeiden. Rein dokumentarisch.
[EN] Marks step 2 of Bild 1 (§ 4/§ 5.3, printed pp. 11–12/13): "Develop concept (overall system)" — the actual concept is produced here; single measures and their investments are often avoided through this system-level view. Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_2_konzept_gesamtsystem';
UPDATE fields x SET description = 'Markiert Schritt 3 aus Bild 1 (§ 5.4, gedruckt S. 13): „Projekte identifizieren und definieren“ — alle zur Umsetzung der Gesamtmaßnahme nötigen Einzelprojekte werden festgelegt. Rein dokumentarisch.
[EN] Marks step 3 of Bild 1 (§ 5.4, printed p. 13): "Identify and define projects" — all single projects required to realise the overall measure are identified. Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_3_identifikation_projekte';
UPDATE fields x SET description = 'Markiert Schritt 4 aus Bild 1 (§ 6.1, gedruckt S. 14): jedes identifizierte Projekt durchläuft seinen eigenen Lebenszyklus Bedarfsplanung Projekt → Planung → Ausführungsvorbereitung → Ausführung → Inbetriebnahme/Abnahme → Projektabschluss (§ 6.2–6.7). Rein dokumentarisch.
[EN] Marks step 4 of Bild 1 (§ 6.1, printed p. 14): each identified project then runs its own lifecycle Bedarfsplanung Projekt → Planung → Ausführungsvorbereitung → Ausführung → commissioning/acceptance → project closure (§ 6.2–6.7). Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'bild1_step_4_einzelprojekt_lifecycle';
UPDATE fields x SET description = 'Bestätigt Kenntnisnahme der DWA-Klimakennung KA1 (Vorwort, gedruckt S. 3): „Das Merkblatt hat indirekten Bezug zur Klimaanpassung.“ Reine Kenntnisnahme, keine Prüfpflicht.
[EN] Confirms awareness of the DWA climate code KA1 (Vorwort, printed p. 3): "The Merkblatt has an indirect link to climate adaptation." Acknowledgement only, no enforced duty.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'klimakennung_ka1';
UPDATE fields x SET description = 'Bestätigt Kenntnisnahme der DWA-Klimakennung KS1 (Vorwort, gedruckt S. 3): „Das Merkblatt hat indirekten Bezug zu Klimaschutzparametern.“ Reine Kenntnisnahme.
[EN] Confirms awareness of the DWA climate code KS1 (Vorwort, printed p. 3): "The Merkblatt has an indirect link to climate-protection parameters." Acknowledgement only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'klimakennung_ks1';
UPDATE fields x SET description = 'Bestätigt die Definition „Phase“ (§ 2.1, gedruckt S. 8): „bestimmter Abschnitt des gesamten Projektablaufs, der einen eindeutigen Beginn und ein definiertes Ende aufweist.“ Prüfung REQ-03 (Warnung).
[EN] Confirms the definition of "Phase" (§ 2.1, printed p. 8): "a defined section of the entire project process with a clear start and a defined end." Checked by warning gate REQ-03.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'phase_definition_acknowledged';
UPDATE fields x SET description = 'Bestätigt die Definition „Phasenziele“ (§ 2.1, gedruckt S. 8): „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind.“ Prüfung REQ-03 (Warnung).
[EN] Confirms the definition of "Phasenziele" (§ 2.1, printed p. 8): "results to be achieved after completion of the respective service phase." Checked by warning gate REQ-03.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'phasenziele_definition_acknowledged';
UPDATE fields x SET description = 'Bestätigt die Definition „Projektziele“ (§ 2.1, gedruckt S. 8): „Gesamtheit von Einzelzielen, die durch das Projekt erreicht werden“ — nach DIN 18205:2016 beispielhaft in vier Kategorien (funktional/technisch, soziokulturell/gestalterisch, ökonomisch/zeitlich, ökologisch). Prüfung REQ-03.
[EN] Confirms the definition of "Projektziele" (§ 2.1, printed p. 8): "the totality of individual goals to be achieved by the project" — per DIN 18205:2016 exemplified in four categories (functional/technical, socio-cultural/design, economic/time, ecological). Checked by REQ-03.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'projektziele_definition_acknowledged';
UPDATE fields x SET description = 'Bestätigt die Definition „Qualitätselemente/-kriterien“ (§ 2.1, gedruckt S. 8): „definierte Leistungsbestandteile der jeweils zuständigen Projektbeteiligten, deren Erfüllung nachprüfbar ist und die für das Erreichen der Phasenziele erforderlich sind.“ Prüfung REQ-03.
[EN] Confirms the definition of "Qualitätselemente/-kriterien" (§ 2.1, printed p. 8): "defined service components of the respective responsible project participants, whose fulfilment is verifiable and required to achieve the phase goals." Checked by REQ-03.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'qe_definition_acknowledged';
UPDATE fields x SET description = 'Bestätigt den Rahmen (§ 4, gedruckt S. 11–12): alle zusammenwirkenden Anlagenteile (z. B. Kläranlagen, Kanäle, Niederschlagswasserbehandlung) werden im Konzept Gesamtsystem als Ganzes betrachtet. Rein dokumentarisch.
[EN] Confirms the framework (§ 4, printed pp. 11–12): all interacting facility parts (e.g. treatment plants, sewers, stormwater treatment) are considered holistically within the overall-system concept. Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'rahmen_system_aggregation_acknowledged';
UPDATE fields x SET description = 'Bestätigt den Rahmen (§ 4, gedruckt S. 12): eine sorgfältige Bestandsanalyse liefert valide Grundlagen für das Konzept; dadurch lassen sich Einzelmaßnahmen und nötige Investitionen oft vermeiden. Rein dokumentarisch.
[EN] Confirms the framework (§ 4, printed p. 12): a careful existing-state analysis provides a valid foundation for the concept; this view often avoids single measures and the investments they would require. Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'rahmen_valid_existing_data_basis';
UPDATE fields x SET description = 'Bestätigt die Aussage des Vorworts (gedruckt S. 3): „Direkte Kosten- und/oder Umweltauswirkungen sind durch dieses Merkblatt nicht zu erwarten.“ Konsequente Anwendung verbessert Projektabläufe und kann Lebenszykluskosten senken. Rein dokumentarisch.
[EN] Confirms the Vorwort''s statement (printed p. 3): "Direct cost and/or environmental impacts are not to be expected from this Merkblatt." Consistent application improves project workflows and can reduce lifecycle costs. Documentary only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.symbol = 'vorwort_indirect_cost_env_impact';
UPDATE compliance_requirements x SET description = 'Warnprüfung, gilt immer: bestanden, wenn die vier Begriffe Phase, Phasenziele, Projektziele und Qualitätselemente (§ 2.1, gedruckt S. 8) auf diesem Blatt bestätigt sind. „Die Begriffe … gelten inhaltlich unverändert auch in diesem dritten Teil.“ Keine gedruckte Pflicht zur Kenntnisnahme: Warnung.
[EN] Warning gate, always applies: passes when the four terms phase, phase goals, project goals and quality elements (§ 2.1, printed p. 8) are confirmed on this sheet. "The terms … apply unchanged in content in this third part as well." No printed duty to acknowledge: warning.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.code = 'REQ-03';
UPDATE compliance_requirements x SET description = 'Warnprüfung, gilt immer: bestanden, wenn „Bild 1 übernommen“ auf diesem Blatt bejaht ist. § 4 (gedruckt S. 11): Bild 1 gibt „den vorgeschlagenen grundsätzlichen Ablauf“ wieder. Keine gedruckte Pflicht: Warnung.
[EN] Warning gate, always applies: passes when "Bild 1 adopted" is Yes on this sheet. § 4 (printed p. 11): Bild 1 shows "the proposed basic process". No printed duty: warning.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-03' AND x.code = 'REQ-04';
UPDATE fields x SET description = 'Status zu Phasenziel 1 (§ 5.2, gedruckt S. 12): „Die ''Bedarfsplanung Konzept'' sollte alle Rahmenbedingungen und Aspekte erfassen, die ein Bauherr im Hinblick auf Visionen sowie technische und strategische Ziele verfolgt. Das bestehende Gesamtsystem ist bekannt.“ Bestanden bei Erreicht/Teilweise erreicht/Nicht zutreffend/Phase noch nicht erreicht; „Nicht erreicht“ blockiert REQ-06 (nur bei Projekttyp Gesamtsystem oder Beides).
[EN] Status for phase goal 1 (§ 5.2, printed p. 12): "The ''Bedarfsplanung Konzept'' should capture all framework conditions and aspects a client pursues regarding visions and technical/strategic goals. The existing overall system is known." Passes at met/partially met/not applicable/not reached yet; "not met" blocks REQ-06 (only for project type overall system or both).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_1_status';
UPDATE fields x SET description = 'Status zu Phasenziel 2 (§ 5.2, gedruckt S. 12): „Entwicklungsprognosen und zukünftige technische, ökologische und gesetzliche Anforderungen sind mit den zuständigen Behörden und Fachbereichen geklärt. Randbedingungen anderer Beteiligter und betroffener Stakeholder sind geklärt.“ Geprüft von REQ-06.
[EN] Status for phase goal 2 (§ 5.2, printed p. 12): "Development forecasts and future technical, ecological and legal requirements are clarified with the competent authorities and departments. Boundary conditions of other parties and affected stakeholders are clarified." Checked by REQ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_2_status';
UPDATE fields x SET description = 'Status zu Phasenziel 3 (§ 5.2, gedruckt S. 12): „Die Prioritäten von Terminen, Kosten und Qualitäten müssen sowohl für das Gesamtsystem als auch für die einzelnen Projekte festgelegt und kommuniziert werden.“ Geprüft von REQ-06.
[EN] Status for phase goal 3 (§ 5.2, printed p. 12): "The priorities of schedule, cost and quality must be set and communicated both for the overall system and for the individual projects." Checked by REQ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_3_status';
UPDATE fields x SET description = 'Status zu Phasenziel 4 (§ 5.2, gedruckt S. 12): „Die Projektmanagementstrukturen sind geklärt und kommuniziert.“ Geprüft von REQ-06.
[EN] Status for phase goal 4 (§ 5.2, printed p. 12): "The project management structures are clarified and communicated." Checked by REQ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_4_status';
UPDATE fields x SET description = 'Status zu Phasenziel 5 (§ 5.2, gedruckt S. 12): „Die Planungstiefe für zu entwickelnde Maßnahmen ist definiert.“ Geprüft von REQ-06.
[EN] Status for phase goal 5 (§ 5.2, printed p. 12): "The planning depth for the measures to be developed is defined." Checked by REQ-06.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_5_status';
UPDATE fields x SET description = 'Ja/Nein: wurde bei nicht oder nur teilweise erreichten Phasenzielen dieses Blatts eine Projektstopp-Prüfung mit Risikoanalyse durchgeführt? § 3 (gedruckt S. 10): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Blockiert REQ-06-2, falls Nein. Ergebnis auf M8203-24 eintragen.
[EN] Yes/No: when a phase goal on this sheet is not met or only partially met, was a Projektstopp review with risk analysis carried out? § 3 (printed p. 10): "...a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Blocks REQ-06-2 if No. Record the outcome on M8203-24.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.symbol = 'pz_52_projektstopp_risikoanalyse';
UPDATE compliance_requirements x SET description = 'Blockierende Prüfung, nur bei Projekttyp Gesamtsystem oder Beides (M8203-01): bestanden, wenn jedes der fünf Phasenziele von § 5.2 (gedruckt S. 12) einen Status hat und keines „Nicht erreicht“ ist. Solange ein Status fehlt, wartet die Prüfung. Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, S. 8).
[EN] Block gate, only for project type overall system or both (M8203-01): passes when each of the five phase goals of § 5.2 (printed p. 12) has a status and none is "not met". While a status is missing the check waits. Phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1, p. 8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06';
UPDATE compliance_requirements x SET description = 'Blockierende Prüfung: ist ein Phasenziel § 5.2 „Nicht erreicht“ oder „Teilweise erreicht“, muss die Projektstopp-Prüfung mit Risikoanalyse (dieses Blatt) bejaht sein. § 3 (gedruckt S. 10): „...ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden...“ Modalverben „erforderlich“/„muss“ → Blockade.
[EN] Block gate: if a § 5.2 phase goal is "not met" or "partially met", the Projektstopp review with risk analysis (this sheet) must be Yes. § 3 (printed p. 10): "...a Projektstopp review is required. A risk analysis must assess..." Modal verbs "required"/"must" → block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06-2';
UPDATE compliance_requirements x SET description = 'Warnprüfung, gilt immer: erscheint, solange ein Phasenziel von § 5.2 auf diesem Blatt „Phase noch nicht erreicht“ hat, und entfällt, sobald jedes Ziel bewertet ist. Prüfen Sie, ob die Phase wirklich noch bevorsteht. § 2.1 (gedruckt S. 8): Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“.
[EN] Warning gate, always applies: shows while any § 5.2 phase goal on this sheet is "phase not reached yet" and clears once every goal is rated. Check that the phase really is still ahead. § 2.1 (printed p. 8): phase goals are "results to be achieved after completion of the respective service phase".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-04' AND x.code = 'REQ-06-3';
UPDATE fields x SET description = 'Status zu Phasenziel 1 (§ 5.3, gedruckt S. 13): „Das zu erstellende Konzept stellt den IST-Zustand des Gesamtsystems mit allen erforderlichen qualitätsgesicherten Bestandsdaten dar und zeigt Maßnahmen zur Erreichung der in der Bedarfsplanung formulierten Ziele auf.“ Geprüft von REQ-07 (nur bei Projekttyp Gesamtsystem oder Beides).
[EN] Status for phase goal 1 (§ 5.3, printed p. 13): "The concept to be prepared presents the current state of the overall system with all required quality-assured existing data and outlines measures to achieve the goals formulated in the needs planning." Checked by REQ-07 (only for project type overall system or both).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_1_status';
UPDATE fields x SET description = 'Status zu Phasenziel 2 (§ 5.3, gedruckt S. 13): „Die Auswirkungen der Maßnahmen auf das Gesamtsystem wurden ermittelt und bewertet. Hierbei wurden verschiedene Szenarien zur Prognoseentwicklung betrachtet, um ein anpassungsfähiges Konzept zu erstellen.“ Geprüft von REQ-07.
[EN] Status for phase goal 2 (§ 5.3, printed p. 13): "The effects of the measures on the overall system were determined and evaluated. Various scenarios for forecast development were considered to create an adaptable concept." Checked by REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_2_status';
UPDATE fields x SET description = 'Status zu Phasenziel 3 (§ 5.3, gedruckt S. 13): „Es besteht Klarheit, in welcher Reihenfolge die Einzelmaßnahmen zeitlich angeordnet sein müssen, um den optimalen Erfolg zu erreichen. Synergieeffekte wurden berücksichtigt.“ Geprüft von REQ-07.
[EN] Status for phase goal 3 (§ 5.3, printed p. 13): "There is clarity on the order in which the single measures must be scheduled to achieve the optimal result. Synergy effects were considered." Checked by REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_3_status';
UPDATE fields x SET description = 'Status zu Phasenziel 4 (§ 5.3, gedruckt S. 13): „Die Untersuchung von Alternativen nach grundsätzlich verschiedenen Anforderungen wurde durchgeführt und ist abgeschlossen. Durchzuführende Projekte sind eindeutig definiert und die Prioritäten festgelegt.“ Geprüft von REQ-07.
[EN] Status for phase goal 4 (§ 5.3, printed p. 13): "The investigation of alternatives according to fundamentally different requirements was carried out and is complete. Projects to be carried out are clearly defined and priorities set." Checked by REQ-07.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-05' AND x.symbol = 'pz_53_4_status';
UPDATE fields x SET description = 'Status zu Phasenziel 5 (§ 5.3, gedruckt S. 13): „Der auftraggeberseitige Freigabeprozess für das Konzept ist abgeschlossen.“ Geprüft von REQ-07.
