UPDATE equations x SET description = 'Zählt im Register qe53_items, wie viele der 8 gedruckten Kriterien aus Anhang A.2 mit N (nicht erfüllt) bewertet sind. Speist qe53_items_n_calc.
[EN] Counts in the register qe53_items how many of the 8 printed Anhang A.2 criteria are rated N (not fulfilled). Feeds qe53_items_n_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-08' AND x.equation_number = 'M8203-08-D3';
UPDATE equations x SET description = 'Zählt im Register qe53_items, wie viele der 8 gedruckten Kriterien aus Anhang A.2 als NA (nicht zutreffend) markiert sind. Speist qe53_items_na_calc.
[EN] Counts in the register qe53_items how many of the 8 printed Anhang A.2 criteria are marked NA (not applicable). Feeds qe53_items_na_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-08' AND x.equation_number = 'M8203-08-D4';
UPDATE equations x SET description = 'Zählt alle Zeilen im Register qe53_items, unabhängig davon ob sie bewertet sind. Speist qe53_items_rated; bei 8 gedruckten Kriterien aus Anhang A.2 entspricht das der Zeilenzahl im Register, nicht zwingend der Anzahl bewerteter Kriterien.
[EN] Counts all rows in the register qe53_items, regardless of whether they are rated. Feeds qe53_items_rated; for the 8 printed Anhang A.2 criteria this is the register''s row count, not necessarily the number of rated criteria.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-08' AND x.equation_number = 'M8203-08-D5';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit Y bewerteten Kriterien an den 8 gedruckten Kriterien aus Anhang A.2 (Zähler aus dem Register, Nenner qe53_items_total). Speist qe53_share_y_pct.
[EN] Computes the percentage share of criteria rated Y among the 8 printed Anhang A.2 criteria (numerator from the register, denominator qe53_items_total). Feeds qe53_share_y_pct.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-08' AND x.equation_number = 'M8203-08-D6';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit P bewerteten Kriterien an den 8 gedruckten Kriterien aus Anhang A.2 (Zähler aus dem Register, Nenner qe53_items_total). Speist qe53_share_p_pct.
