UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit N bewerteten Kriterien an den 8 gedruckten Kriterien aus Anhang A.2 (Zähler aus dem Register, Nenner qe53_items_total). Speist qe53_share_n_pct.
