UPDATE fields x SET description = 'Eine Zeile je gedrucktem Element aus Anhang A.3 (12 Kriterien (Nr. 1–12)): Kriterium/Hinweis wie im Merkblatt, Ihre Bewertung (Y/P/N/NA), Nachweis und Bemerkung. Fügen Sie eine Zeile je Kriterium hinzu; die Y/P/N/NA-Skala ist eine Werkzeugkonvention zur Erfassung, keine gedruckte Vorgabe.
[EN] One row per printed Anhang A.3 item (12 criteria (No. 1–12)): the criterion/hint as printed, your rating (Y/P/N/NA), evidence and remark. Add one row per criterion; the Y/P/N/NA scale is the tool''s own recording convention, not a printed requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-09' AND x.symbol = 'qe54_items';
