UPDATE equations x SET description = 'Zählt alle Zeilen im Register qe54_items, unabhängig davon ob sie bewertet sind. Speist qe54_items_rated; bei 12 gedruckten Kriterien aus Anhang A.3 entspricht das der Zeilenzahl im Register, nicht zwingend der Anzahl bewerteter Kriterien.
