UPDATE fields x SET description = 'Anzahl der 3 Kategorien (Ökonomie, Ökologie, Sozioökonomie) aus Anhang A.4, die Sie als Y (erfüllt) bewertet haben. Zusammen mit P/N/NA sollte die Summe der Gesamtzahl (3) entsprechen; sonst zeigt die Prüfung REQ-18 eine Warnung.
[EN] Count of the 3 categories (economy, ecology, socio-economy) of Anhang A.4 you rated Y (fulfilled). Together with P/N/NA the sum should equal the total (3); otherwise check REQ-18 shows a warning.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_y';
UPDATE fields x SET description = 'Eine Zeile je gedrucktem Element aus Anhang A.4 (3 Kategorien (Ökonomie, Ökologie, Sozioökonomie)): Kriterium/Hinweis wie im Merkblatt, Ihre Bewertung (Y/P/N/NA), Nachweis und Bemerkung. Fügen Sie eine Zeile je Kriterium hinzu; die Y/P/N/NA-Skala ist eine Werkzeugkonvention zur Erfassung, keine gedruckte Vorgabe.
[EN] One row per printed Anhang A.4 item (3 categories (economy, ecology, socio-economy)): the criterion/hint as printed, your rating (Y/P/N/NA), evidence and remark. Add one row per criterion; the Y/P/N/NA scale is the tool''s own recording convention, not a printed requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items';
UPDATE fields x SET description = 'Berechnet, wie viele Zeilen im Register oben angelegt sind (Gleichung M8203-10-D5), unabhängig von der Bewertung. Zeigt, ob bereits alle 3 gedruckten Kriterien aus Anhang A.4 als Zeile erfasst wurden.
[EN] Computed count of rows present in the register above (equation M8203-10-D5), regardless of rating. Shows whether all 3 printed Anhang A.4 criteria have been added as a row yet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_rated';
UPDATE fields x SET description = 'Berechnet aus dem Register oben, wie viele der 3 Kriterien mit Y bewertet sind (Gleichung M8203-10-D1). Sollte mit dem manuellen Feld qe55_items_y übereinstimmen; die Prüfung REQ-18 verwendet das manuelle Feld.
[EN] Computed from the register above: how many of the 3 criteria are rated Y (equation M8203-10-D1). Should match the manual field qe55_items_y; check REQ-18 uses the manual field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_y_calc';
UPDATE fields x SET description = 'Berechnet aus dem Register oben, wie viele der 3 Kriterien mit P bewertet sind (Gleichung M8203-10-D2). Sollte mit dem manuellen Feld qe55_items_p übereinstimmen; die Prüfung REQ-18 verwendet das manuelle Feld.
[EN] Computed from the register above: how many of the 3 criteria are rated P (equation M8203-10-D2). Should match the manual field qe55_items_p; check REQ-18 uses the manual field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_p_calc';
UPDATE fields x SET description = 'Berechnet aus dem Register oben, wie viele der 3 Kriterien mit N bewertet sind (Gleichung M8203-10-D3). Sollte mit dem manuellen Feld qe55_items_n übereinstimmen; die Prüfung REQ-18 verwendet das manuelle Feld.
[EN] Computed from the register above: how many of the 3 criteria are rated N (equation M8203-10-D3). Should match the manual field qe55_items_n; check REQ-18 uses the manual field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_n_calc';
UPDATE fields x SET description = 'Berechnet aus dem Register oben, wie viele der 3 Kriterien mit NA bewertet sind (Gleichung M8203-10-D4). Sollte mit dem manuellen Feld qe55_items_na übereinstimmen; die Prüfung REQ-18 verwendet das manuelle Feld.
[EN] Computed from the register above: how many of the 3 criteria are rated NA (equation M8203-10-D4). Should match the manual field qe55_items_na; check REQ-18 uses the manual field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_items_na_calc';
UPDATE fields x SET description = 'Berechnet den Anteil der mit Y bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Gleichung M8203-10-D6). Kein Erfüllungsgrad — P-Gewichtung und NA-Behandlung sind im Merkblatt nicht festgelegt.
[EN] Computed share of criteria rated Y among the 3 printed Anhang A.4 criteria (equation M8203-10-D6). Not a fulfilment rate — the guideline fixes no P-weighting or NA treatment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_share_y_pct';
UPDATE fields x SET description = 'Berechnet den Anteil der mit P bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Gleichung M8203-10-D7). Kein Erfüllungsgrad — P-Gewichtung und NA-Behandlung sind im Merkblatt nicht festgelegt.
[EN] Computed share of criteria rated P among the 3 printed Anhang A.4 criteria (equation M8203-10-D7). Not a fulfilment rate — the guideline fixes no P-weighting or NA treatment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_share_p_pct';
UPDATE fields x SET description = 'Berechnet den Anteil der mit N bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Gleichung M8203-10-D8). Kein Erfüllungsgrad — P-Gewichtung und NA-Behandlung sind im Merkblatt nicht festgelegt.
[EN] Computed share of criteria rated N among the 3 printed Anhang A.4 criteria (equation M8203-10-D8). Not a fulfilment rate — the guideline fixes no P-weighting or NA treatment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_share_n_pct';
UPDATE fields x SET description = 'Berechnet den Anteil der als NA markierten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Gleichung M8203-10-D9). Kein Erfüllungsgrad — P-Gewichtung und NA-Behandlung sind im Merkblatt nicht festgelegt.
[EN] Computed share of criteria marked NA among the 3 printed Anhang A.4 criteria (equation M8203-10-D9). Not a fulfilment rate — the guideline fixes no P-weighting or NA treatment.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.symbol = 'qe55_share_na_pct';
UPDATE equations x SET description = 'Zählt im Register qe55_items, wie viele der 3 gedruckten Kriterien aus Anhang A.4 mit Y (erfüllt) bewertet sind. Speist qe55_items_y_calc.
[EN] Counts in the register qe55_items how many of the 3 printed Anhang A.4 criteria are rated Y (fulfilled). Feeds qe55_items_y_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D1';
UPDATE equations x SET description = 'Zählt im Register qe55_items, wie viele der 3 gedruckten Kriterien aus Anhang A.4 mit P (teilweise erfüllt) bewertet sind. Speist qe55_items_p_calc.
[EN] Counts in the register qe55_items how many of the 3 printed Anhang A.4 criteria are rated P (partially fulfilled). Feeds qe55_items_p_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D2';
UPDATE equations x SET description = 'Zählt im Register qe55_items, wie viele der 3 gedruckten Kriterien aus Anhang A.4 mit N (nicht erfüllt) bewertet sind. Speist qe55_items_n_calc.
[EN] Counts in the register qe55_items how many of the 3 printed Anhang A.4 criteria are rated N (not fulfilled). Feeds qe55_items_n_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D3';
UPDATE equations x SET description = 'Zählt im Register qe55_items, wie viele der 3 gedruckten Kriterien aus Anhang A.4 als NA (nicht zutreffend) markiert sind. Speist qe55_items_na_calc.
[EN] Counts in the register qe55_items how many of the 3 printed Anhang A.4 criteria are marked NA (not applicable). Feeds qe55_items_na_calc.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D4';
UPDATE equations x SET description = 'Zählt alle Zeilen im Register qe55_items, unabhängig davon ob sie bewertet sind. Speist qe55_items_rated; bei 3 gedruckten Kriterien aus Anhang A.4 entspricht das der Zeilenzahl im Register, nicht zwingend der Anzahl bewerteter Kriterien.
[EN] Counts all rows in the register qe55_items, regardless of whether they are rated. Feeds qe55_items_rated; for the 3 printed Anhang A.4 criteria this is the register''s row count, not necessarily the number of rated criteria.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D5';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit Y bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Zähler aus dem Register, Nenner qe55_items_total). Speist qe55_share_y_pct.
[EN] Computes the percentage share of criteria rated Y among the 3 printed Anhang A.4 criteria (numerator from the register, denominator qe55_items_total). Feeds qe55_share_y_pct.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D6';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit P bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Zähler aus dem Register, Nenner qe55_items_total). Speist qe55_share_p_pct.
[EN] Computes the percentage share of criteria rated P among the 3 printed Anhang A.4 criteria (numerator from the register, denominator qe55_items_total). Feeds qe55_share_p_pct.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D7';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der mit N bewerteten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Zähler aus dem Register, Nenner qe55_items_total). Speist qe55_share_n_pct.
[EN] Computes the percentage share of criteria rated N among the 3 printed Anhang A.4 criteria (numerator from the register, denominator qe55_items_total). Feeds qe55_share_n_pct.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D8';
UPDATE equations x SET description = 'Berechnet den Prozentanteil der als NA markierten Kriterien an den 3 gedruckten Kriterien aus Anhang A.4 (Zähler aus dem Register, Nenner qe55_items_total). Speist qe55_share_na_pct.
[EN] Computes the percentage share of criteria marked NA among the 3 printed Anhang A.4 criteria (numerator from the register, denominator qe55_items_total). Feeds qe55_share_na_pct.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.equation_number = 'M8203-10-D9';
UPDATE compliance_requirements x SET description = 'Prüft, ob Ihre manuellen Zählfelder Y+P+N+NA aller 3 gedruckten Kriterien aus Anhang A.4 (QE 5.5: Matrix Nachhaltigkeit) die Gesamtzahl 3 ergeben. Das Merkblatt sieht die Prüfung der Phasenziele mit diesen Qualitätselementen als Möglichkeit vor (Vorwort, S. 3: „kann … überprüft werden“); die Prüfung ist daher eine Warnung, kein Blocker. Gilt für jedes Projekt mit diesem Arbeitsblatt; maßgeblich sind die vier Zählfelder Y/P/N/NA und die Gesamtzahl. Zum Bestehen: bewerten Sie alle 3 Kriterien (z. B. im Register) und tragen Sie die Anzahlen Y, P, N und NA in die Zählfelder ein, sodass ihre Summe der Gesamtzahl entspricht.
[EN] Checks whether your manual count fields Y+P+N+NA across all 3 printed Anhang A.4 criteria (QE 5.5: Sustainability matrix) add up to 3. The guideline offers these quality elements as a means to check the Phasenziele (Vorwort, p. 3: „kann … überprüft werden“); the check is therefore a warning, not a blocker. Applies to every project using this sheet; driven by the four count fields Y/P/N/NA and the total. To pass: rate all 3 criteria (e.g. in the register) and enter the Y, P, N and NA counts in the count fields so that their sum equals the total.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-10' AND x.code = 'REQ-18';
UPDATE fields x SET description = 'PZ 6.2-1 (§6.2 Phasenziele, gedr. S. 14): Die „Bedarfsplanung Projekt“ beschreibt die Anforderungen und Rahmenbedingungen so ausführlich und konkret, dass Bauherr und Planende ein gleiches Verständnis der Projektaufgabe entwickeln und klären können, welche Leistungen in Eigenleistung erbracht und welche vergeben werden müssen. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist).
[EN] PZ 6.2-1 (§ 6.2 phase goals, printed p. 14): ''Needs planning (project)'' describes the requirements and framework conditions in enough detail that client and planner develop a shared understanding of the task and clarify which services are performed in-house and which are awarded. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'pz_62_1_status';
UPDATE fields x SET description = 'PZ 6.2-2 (§6.2 Phasenziele, gedr. S. 14): Wurde vorab ein Konzept für das Gesamtsystem erstellt, sind dessen Ergebnisse in die Aufstellung der Bedarfsplanung für dieses Projekt integriert. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist).
[EN] PZ 6.2-2 (§ 6.2 phase goals, printed p. 14): If a concept for the overall system was created beforehand, its results are integrated into this project''s needs-planning document. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'pz_62_2_status';
UPDATE fields x SET description = 'PZ 6.2-3 (§6.2 Phasenziele, gedr. S. 14): Alle erforderlichen Leistungen – Grundleistungen wie besondere Leistungen – sind erfasst, damit ein aussagekräftiger und belastbarer Ingenieurvertrag geschlossen werden kann. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist).
[EN] PZ 6.2-3 (§ 6.2 phase goals, printed p. 14): All required services – basic and special services alike – are captured, so that a meaningful and robust engineering contract can be concluded. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'pz_62_3_status';
UPDATE fields x SET description = 'PZ 6.2-4 (§6.2 Phasenziele, gedr. S. 14): Anforderungen, Ziele und Prioritäten zwischen Terminen, Kosten und Qualitäten sind definiert und den Planenden bekannt; verfügbare Ressourcen und Kapazitäten aller Projektbeteiligten (inkl. AG) sind berücksichtigt, auch für digitale Planungsmethoden. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist).
[EN] PZ 6.2-4 (§ 6.2 phase goals, printed p. 14): Requirements, goals and priorities between schedule, cost and quality are defined and known to the planners; available resources and capacities of all project parties (incl. client) are accounted for, including for digital planning methods. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'pz_62_4_status';
UPDATE fields x SET description = 'PZ 6.2-5 (§6.2 Phasenziele, gedr. S. 14): Projektmanagement-, Kommunikations- und Entscheidungsstrukturen sind geklärt, kommuniziert und kalkulierbar; Verantwortlichkeiten und Kompetenzen sind geklärt. Bewerten Sie: Erreicht / Teilweise erreicht (löst die Projektstopp-Prüfung unten aus) / Nicht erreicht (blockiert bei Projekttyp Einzelprojekt oder Beides) / Nicht zutreffend / Phase noch nicht erreicht (nur wählen, wenn die Leistungsphase wirklich noch nicht abgeschlossen ist).
[EN] PZ 6.2-5 (§ 6.2 phase goals, printed p. 14): Project-management, communication and decision-making structures are clarified, communicated and predictable; responsibilities and competencies are clarified. Rate it: Met / Partially met (triggers the Projektstopp review below) / Not met (blocks for project type einzelprojekt or both) / Not applicable / Phase not reached yet (choose only if the service phase genuinely has not closed).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'pz_62_5_status';
UPDATE fields x SET description = 'Datum, an dem Sie diese QE-Prüfung (QE 6.2: Bedarfsplanung Projekt) durchgeführt haben. Reines Dokumentationsfeld des Wizards – das Merkblatt schreibt kein Bewertungsdatum vor; es hält fest, wann die Y/P/N/NA-Einstufungen unten galten.
[EN] Date you carried out this QE assessment (QE 6.2: needs planning (project)). A tool documentation field – the guideline does not prescribe an assessment date; it records when the Y/P/N/NA ratings below applied.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_assessment_date';
UPDATE fields x SET description = 'Person oder Rolle, die diese QE-Prüfung durchgeführt hat (z. B. Projektleitung, Qualitätsbeauftragter). Reines Dokumentationsfeld des Wizards; das Merkblatt schreibt keinen bestimmten Prüfer vor.
[EN] Person or role who carried out this QE assessment (e.g. project lead, quality officer). A tool documentation field – the guideline does not prescribe who performs it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_assessor';
UPDATE fields x SET description = 'Ja/Nein-Feld: hält fest, ob Sie aus den N- oder P-Einstufungen im Register unten Korrekturmaßnahmen ableiten. Reines Dokumentationsfeld des Wizards; das Merkblatt schreibt dazu nichts vor.
[EN] Yes/No field: records whether you derive corrective actions from the N or P ratings in the register below. A tool documentation field – the guideline prescribes nothing here.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_corrective_actions';
UPDATE fields x SET description = 'Freitext: welche N- oder P-Kriterien aus dem Register unten so schwerwiegend sind, dass sie die Phasenziele dieses Blatts gefährden. Führt das dazu, dass ein Phasenziel oben „Nicht erreicht“ oder „Teilweise erreicht“ wird, verlangt § 3 (gedr. S. 10) eine Projektstopp-Prüfung mit Risikoanalyse – das zugehörige Feld steht auf diesem Blatt.
[EN] Free text: which N or P criteria from the register below are serious enough to put this sheet''s phase goals at risk. If that makes a phase goal above ''Not met'' or ''Partially met'', § 3 (printed p. 10) requires a Projektstopp review with risk analysis – its field sits on this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_critical_gaps';
UPDATE fields x SET description = 'Ihre Gesamteinschätzung des Erfüllungsgrads dieser Checkliste in %, gestützt auf die Y/P/N/NA-Zählungen unten. Das Merkblatt schreibt keine Formel vor, wie Teilerfüllungen (P) oder nicht zutreffende Kriterien (NA) zu gewichten sind – die Gewichtung bleibt Ihre fachliche Einschätzung.
[EN] Your overall estimate of this checklist''s fulfilment rate in %, based on the Y/P/N/NA counts below. The guideline prints no formula for weighting partial (P) or not-applicable (NA) criteria – the weighting is your engineering judgement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_fulfilment_pct';
UPDATE fields x SET description = 'Anzahl der Kriterien aus dem Register unten, die Sie mit N bewertet haben; Sie tragen die Zahl selbst ein. Der Vollständigkeits-Check oben (REQ-19) liest dieses Feld zusammen mit den Y-, P- und NA-Zahlen und der Gesamtzahl.
[EN] Number of criteria from the register below that you rated N; you enter it yourself. The completeness check above (REQ-19) reads this field together with the Y, P and NA counts and the total.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_items_n';
UPDATE fields x SET description = 'Anzahl der Kriterien, die Sie als NA (nicht zutreffend) markiert haben – Kriterien aus der Auswahl, die für dieses Projekt nicht gelten. Laut Vorwort (gedr. S. 3) sind die Qualitätselemente nur eine projektübergeordnete Auswahl an Kriterien, die projektspezifisch ausgewählt und ergänzt werden müssen.
[EN] Number of criteria you marked NA (not applicable) – criteria from the selection that do not apply to this project. Per the Vorwort (printed p. 3), the quality elements are only a project-overarching selection of criteria that must be selected and supplemented project-specifically.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-11' AND x.symbol = 'qe62_items_na';
