UPDATE equations x SET description = 'Zählt automatisch, wie viele Zeilen im Kriterien-Register qe64a_items mit Y (erfüllt) bewertet sind. Zählt nur Zeilen, deren Katalognummer in diesem Teil liegt (Nr. 1–17). Ergebnis speist das Informationsfeld qe64a_items_y_calc; auf diesem Blatt an keine Prüfung angeschlossen.
