UPDATE equations x SET description = 'Zählt automatisch alle Zeilen im Register qe64a_items (unabhängig von der Bewertung). Zählt nur Zeilen, deren Katalognummer in diesem Teil liegt (Nr. 1–17). Zum Vergleich: Anh. B.3 druckt 17 Kriterien (Nr. 1–17).
[EN] Automatically counts all rows in the register qe64a_items (whatever their rating). Counts only rows whose catalogue number lies in this part''s range (Nr. 1–17). For comparison: Anh. B.3 prints 17 criteria (Nr. 1–17).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-14' AND x.equation_number = 'M8203-14-D5';
